import sys,json
from typing import List

class Solution:
 def pathsWithMaxScore(self, board: List[str]) -> List[int]:
  MOD=1000000007; n=len(board); best=[[-1]*n for _ in range(n)]; ways=[[0]*n for _ in range(n)]; best[-1][-1]=0; ways[-1][-1]=1
  for r in range(n-1,-1,-1):
   for c in range(n-1,-1,-1):
    ch=board[r][c]
    if ch in 'XS': continue
    mx=-1; cnt=0
    for dr,dc in ((1,0),(0,1),(1,1)):
     nr,nc=r+dr,c+dc
     if nr<n and nc<n and ways[nr][nc]:
      if best[nr][nc]>mx: mx=best[nr][nc]; cnt=ways[nr][nc]
      elif best[nr][nc]==mx: cnt=(cnt+ways[nr][nc])%MOD
    if cnt: best[r][c]=mx+(0 if ch=='E' else int(ch)); ways[r][c]=cnt
  return [best[0][0],ways[0][0]%MOD] if ways[0][0] else [0,0]

